"""Phase 16 hostile fixtures: loaders and deterministic generators (T7).

Every data file here is untrusted test input. Nothing in this module fetches,
spawns or writes: the 2 MB page and the PDF bombs are built in memory from their
descriptors, so the folder stays small. Hosts in the fixtures are never resolved;
tests serve them through local fakes.

Load this module by path, so no installed package can shadow it:

    spec = importlib.util.spec_from_file_location('p16_kit', FIXTURES / 'kit.py')
    kit = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(kit)
"""

import hashlib
import io
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
NOW = 1_791_800_000.0  # 2026-10-12T09:33:20Z, the host clock for every Phase 16 case
FORMATS = ('pebble-p16-fixture/1', 'pebble-p16-fake-ax/1', 'pebble-p16-fake-mcp/1')
BUDGET_BYTES = 200_000  # the whole folder, generated bytes excluded


def path(name):
    target = (ROOT / name).resolve()
    if ROOT not in target.parents:
        raise ValueError('Fixture paths stay inside the fixture folder.')
    return target


def text(name):
    return path(name).read_text(encoding='utf-8')


def data(name):
    return path(name).read_bytes()


def load(name):
    return json.loads(text(name))


def manifest():
    return load('manifest.json')


def sha256(value):
    return hashlib.sha256(value).hexdigest()


def large_page(spec):
    """W4: HTML a little over the fetch cap. A two-byte character straddles the cap,
    markers sit at fixed paragraphs and the late marker lies wholly past the cap."""
    p = spec['params']
    cap, out, index = p['cap_bytes'], bytearray(p['head'].encode()), 0
    marks = {int(k): v for k, v in p['markers'].items()}
    while len(out) < cap - p['pad_window']:
        line = p['paragraph'].format(i=index)
        if index in marks:
            line = line.replace('</p>', ' ' + marks[index] + '</p>')
        out += line.encode()
        index += 1
    if len(out) > cap - 1:
        raise ValueError('The padding window is smaller than one paragraph.')
    out += b' ' * (cap - 1 - len(out))
    straddle = p['straddle'].encode()
    if len(straddle) != 2:
        raise ValueError('The straddling character must take two UTF-8 bytes.')
    out += straddle  # bytes cap-1 and cap: a prefix of cap bytes cuts it in half
    while len(out) < p['target_bytes']:
        out += p['late'].encode()
    out += p['tail'].encode()
    return bytes(out)


def _writer():
    from pypdf import PdfWriter
    return PdfWriter()


def _text_page(writer, text):
    from pypdf.generic import DecodedStreamObject, DictionaryObject, NameObject
    font = DictionaryObject({NameObject('/Type'): NameObject('/Font'), NameObject('/Subtype'): NameObject('/Type1'),
                             NameObject('/BaseFont'): NameObject('/Helvetica')})
    resources = writer._add_object(DictionaryObject(
        {NameObject('/Font'): DictionaryObject({NameObject('/F1'): writer._add_object(font)})}))
    stream = DecodedStreamObject()
    stream.set_data(b'BT /F1 12 Tf 72 720 Td (' + text.encode('ascii') + b') Tj ET')
    return resources, writer._add_object(stream)


def pdf(spec):
    """W5: a small PDF from a pdf_bombs.json entry ('flate_page', 'many_pages' or 'encrypted')."""
    from pypdf.generic import DecodedStreamObject, NameObject
    kind, params = spec['generator'], spec.get('params', {})
    writer = _writer()
    if kind == 'flate_page':
        page = writer.add_blank_page(width=612, height=792)
        stream = DecodedStreamObject()
        stream.set_data(b' ' * params['expanded_bytes'])
        page[NameObject('/Contents')] = writer._add_object(stream.flate_encode())
    elif kind in ('many_pages', 'encrypted'):
        resources, contents = _text_page(writer, params['text'])
        for _ in range(params.get('pages', 1)):
            page = writer.add_blank_page(width=612, height=792)
            page[NameObject('/Resources')] = resources
            page[NameObject('/Contents')] = contents
        if kind == 'encrypted':
            writer.encrypt(user_password=params['user_password'], algorithm=params['algorithm'])
    else:
        raise ValueError('Unknown PDF generator.')
    out = io.BytesIO()
    writer.write(out)
    return out.getvalue()


TRANSFORMS = ('base64', 'hex', 'urlencoded', 'reversed', 'upper', 'split', 'zero_width', 'gzip')


def echo_body(response, token):
    """C3: the upstream body bytes for one token_echo.json response."""
    import base64
    import gzip
    import urllib.parse
    name = response.get('body_transform')
    body = response.get('body', '').replace('{token}', token)
    if name is None:
        return body.encode()
    if name == 'gzip':
        return gzip.compress(body.encode(), mtime=0)
    value = {'base64': lambda: base64.b64encode(token.encode()).decode(),
             'hex': lambda: token.encode().hex(),
             'urlencoded': lambda: urllib.parse.quote(token, safe=''),
             'reversed': lambda: token[::-1],
             'upper': lambda: token.upper(),
             'split': lambda: json.dumps({'a': token[:len(token) // 2], 'b': token[len(token) // 2:]}),
             'zero_width': lambda: '​'.join(token)}[name]()
    return json.dumps({'debug': value}, ensure_ascii=False).encode()


def fill(template, ids):
    """Replace {primary}-style placeholders with the source IDs a test observed."""
    out = template
    for key, value in ids.items():
        out = out.replace('{' + key + '}', value)
    return out
